def next(self):
    ii = self._iter_index
    if ii < len(self.indices) - 1:
        i0, i1 = self.indices[ii], self.indices[ii + 1]
        self._iter_index += 1
        return self.parent[i0:i1]
    else:
        raise StopIteration

